by_name.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'user' && doc.name) {
    emit(doc.name, doc._id);
  }
}

by_platform.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'user' && doc.platform) {
    emit(doc.platform, doc._id);
  }
}

by_url.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'user' && doc.url) {
    emit(doc.url, doc._id);
  }
}

by_platform_and_name.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'user' && doc.platform && doc.name) {
    emit([doc.platform, doc.name], doc._id);
  }
}
